def convert_waived_to_paid(apps, schema_editor):
    Fine = apps.get_model("fines", "Fine")
    # Step 4: Changes any Waived fine to Paid safely
    for fine in Fine.objects.filter(status="WAIVED"):
        fine.status = "PAID"
        if not fine.payment_reference:
            reason = getattr(fine, 'waiver_reason', '') or 'Admin Waiver'
            fine.payment_reference = f"WAIVED-PAID: {reason}"[:50]
        fine.save()


